const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
for path in sorted(Path('src/handlers').rglob('*')):
    if not path.is_file():
        continue
    try:
        content = path.read_text()
    except (UnicodeError, OSError):
        continue
    updated = content.replace('TIMEOUT_MS = 3000', 'TIMEOUT_MS = 5000')
    if updated == content:
        continue
    try:
        with path.open('w') as file:
            file.write(updated)
        print(f'UPDATED: {path}')
    except OSError as error:
        print(f'DENIED: {path} ({error})')
